import React, { useState } from 'react';
import axios from 'axios';
import '../auth.css';

const Signup = ({ onSignup }) => {
  const [name, setName] = useState('');
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [error, setError] = useState('');
  const [success, setSuccess] = useState('');

  const handleSubmit = async (e) => {
    e.preventDefault();
    try {
      const response = await axios.post('http://localhost:8080/api/auth/signup', {
        name,
        email,
        password
      });

      if (response.data.success) {
        setSuccess(`Account created successfully! Use email: ${email} and your password to login.`);
        setError('');
      }
    } catch (err) {
      setError('Email already exists or invalid data');
      setSuccess('');
    }
  };

  return (
    <div className="signup-page">
      <div className="auth-container">
        <h2>Sign Up</h2>
        <p className="subtitle">or login to your account</p>
        <form onSubmit={handleSubmit}>
        <input
          type="text"
          placeholder="Full Name"
          value={name}
          onChange={(e) => setName(e.target.value)}
          required
        />
        <input
          type="email"
          placeholder="Email"
          value={email}
          onChange={(e) => setEmail(e.target.value)}
          required
        />
        <input
          type="password"
          placeholder="Password"
          value={password}
          onChange={(e) => setPassword(e.target.value)}
          required
        />
        <button type="submit">Sign Up</button>
      </form>
        {error && <div className="error">{error}</div>}
        {success && <div className="success">{success}</div>}
        <p>Already have an account? <button onClick={() => window.location.href = '/login'}>Login</button></p>
      </div>
    </div>
  );
};

export default Signup;
